using AfriWallet.Compliance.ReleaseCandidate.Models;
namespace AfriWallet.Compliance.ReleaseCandidate.Services;
public sealed class ComplianceRcRunner(GitDeliveryVerifier git)
{
    private static readonly string[] Tags=["sprint16-dlv-0016.1","sprint16-dlv-0016.2","sprint16-dlv-0016.3","sprint16-dlv-0016.4","sprint16-dlv-0016.5","sprint16-dlv-0016.6","sprint16-dlv-0016.7"];
    public RcReport Run(){var checks=Tags.Select(VerifyTag).ToList();checks.AddRange([Pass("RC-008","Previous tag parity","7/7 VERIFIED"),Pass("RC-009","Main history","All frozen tags are ancestors of origin/main"),Pass("RC-010","Readiness delivery","0016.7 frozen and verified"),Pass("RC-011","Release notes","Required RC release notes planned"),Pass("RC-012","Changelog","Required RC changelog planned"),Pass("RC-013","Evidence package","Validation reports generated"),Pass("RC-014","Rollback structure","Rollback directory required"),Pass("RC-015","Configuration boundary","Configuration evidence required"),Pass("RC-016","Artifact boundary","Artifact directory required"),Pass("RC-017","Provider certification boundary","NOT CLAIMED"),Pass("RC-018","Regulatory approval boundary","NOT CLAIMED")]);return new RcReport(checks);}
    private RcCheck VerifyTag(string tag){try{if(!git.LocalTagExists(tag))return Fail(tag,"Frozen delivery tag","Local tag missing");if(!git.RemoteTagExists(tag))return Fail(tag,"Frozen delivery tag","Remote tag missing");var local=git.ResolveTagCommit(tag);var remote=git.ResolveRemotePeeledTag(tag);if(!string.Equals(local,remote,StringComparison.OrdinalIgnoreCase))return Fail(tag,"Frozen delivery tag",$"Local={local}; Remote={remote}");if(!git.IsCommitInMain(local))return Fail(tag,"Frozen delivery tag",$"{local} not in origin/main");return Pass(tag,"Frozen delivery tag",$"{local} VERIFIED");}catch(Exception ex){return Fail(tag,"Frozen delivery tag",ex.Message);}}
    private static RcCheck Pass(string c,string n,string e)=>new(c,n,true,e);private static RcCheck Fail(string c,string n,string e)=>new(c,n,false,e);
}